def get_block(partition: PartitionUnionType) -> np.ndarray:
    if isinstance(partition, BaseDataframeAxisPartition):
        # unwrapping remote partitions of a virtual partition is not
        # implemented, so squeezing it into a single block partition first
        partition = partition.force_materialization(get_ip=get_ip)
        return partition.unwrap(squeeze=True, get_ip=get_ip)
    blocks = partition.list_of_blocks
    assert (
        len(blocks) == 1
    ), f"Implementation assumes that partition contains a single block, but {len(blocks)} recieved."
    return blocks[0]

if get_ip:
    return [
        [
            get_block(partition)
            if isinstance(partition, BaseDataframeAxisPartition)
            else (partition._ip_cache, get_block(partition))
            for partition in row
        ]
        for row in modin_frame._partitions
    ]
